from pathlib import Path

root = Path(__file__).resolve().parents[1]

# Bring the print compositor's line-fit model and post-render calibration up to
# the same physical word-gap standard as the live preview. The important bit is
# to reject a too-dense line *before* freezing it into nowrap spans, rather than
# widening spaces afterwards and creating a new page overflow.
compositor = root / "server/pipeline/compositor.ts"
text = compositor.read_text(encoding="utf-8")

fit_old = '''        wordSpacing = Math.max(minWordSpacing, Math.min(maxWordSpacing, wordSpacing));\n        tracking = Math.max(minTracking, Math.min(maxTracking, tracking));\n        const residualPx = (scaledAdjustment - wordSpacing * gaps - tracking * trackingOps) * glyphScale;\n        if (Math.abs(residualPx) > 1.705) continue;\n'''
fit_new = '''        wordSpacing = Math.max(minWordSpacing, Math.min(maxWordSpacing, wordSpacing));\n        tracking = Math.max(minTracking, Math.min(maxTracking, tracking));\n\n        // A line that only fits by visually collapsing whitespace is not a valid\n        // book line. Enforce the physical semantic-gap floor while the breaker is\n        // still choosing candidates, so an earlier legal break wins instead of a\n        // post-render correction widening a frozen nowrap line beyond the page.\n        const physicalGapFloor = Math.max(1.5, fontSize * 0.12);\n        const minimumPhysicalWordSpacing = physicalGapFloor / glyphScale - spaceWidth - tracking;\n        if (minimumPhysicalWordSpacing > maxWordSpacing + 0.000001) continue;\n        if (wordSpacing < minimumPhysicalWordSpacing) {\n          wordSpacing = minimumPhysicalWordSpacing;\n        }\n\n        const residualPx = (scaledAdjustment - wordSpacing * gaps - tracking * trackingOps) * glyphScale;\n        if (Math.abs(residualPx) > 1.705) continue;\n'''
if text.count(fit_old) != 1:
    raise SystemExit(f"fitLine physical-gap anchor: expected 1, found {text.count(fit_old)}")
text = text.replace(fit_old, fit_new)

cal_old = '''      // Mirror live preview exactly: calibrate the final transformed fragment\n      // against Chromium's real rendered width. Platform font rasterizers can\n      // differ slightly from the algebraic width model; correcting scale after\n      // layout keeps export and preview on the same professional measure without\n      // widening any spacing/tracking envelope.\n      const maxAdjacentScaleDelta = 0.012;\n      let previousCorrectedScale: number | null = null;\n      for (const line of lines) {\n        if (!line.classList.contains("folio-line-justified") && !line.classList.contains("folio-line-final-compressed")) {\n          previousCorrectedScale = null;\n          continue;\n        }\n        const content = line.querySelector<HTMLElement>(":scope > .folio-line-content");\n        if (!content) {\n          previousCorrectedScale = null;\n          continue;\n        }\n        const rendered = content.getBoundingClientRect().width;\n        const measure = line.getBoundingClientRect().width;\n        const protrusion = Number(line.dataset.folioRightProtrusion ?? 0);\n        const opticalMeasure = measure + protrusion;\n        const currentScale = Number(line.dataset.folioGlyphScale ?? 1);\n        if (rendered <= 0 || opticalMeasure <= 0 || !Number.isFinite(currentScale)) {\n          previousCorrectedScale = null;\n          continue;\n        }\n        let correctedScale = Math.max(0.99, Math.min(1.01, currentScale * opticalMeasure / rendered));\n        if (previousCorrectedScale !== null) {\n          correctedScale = Math.max(\n            previousCorrectedScale - maxAdjacentScaleDelta,\n            Math.min(previousCorrectedScale + maxAdjacentScaleDelta, correctedScale),\n          );\n          correctedScale = Math.max(0.99, Math.min(1.01, correctedScale));\n        }\n        content.style.transform = Math.abs(correctedScale - 1) > 0.00001\n          ? "scaleX(" + correctedScale + ")"\n          : "";\n        line.dataset.folioGlyphScale = String(correctedScale);\n        previousCorrectedScale = correctedScale;\n      }\n'''
cal_new = '''      // Verify/calibrate what the reader actually sees. fitLine now rejects\n      // candidates below the physical gap floor, so this is only a rasterisation\n      // safety net and should need at most a tiny correction.\n      const maxAdjacentScaleDelta = 0.012;\n      let previousCorrectedScale: number | null = null;\n      for (const line of lines) {\n        if (!line.classList.contains("folio-line-justified") && !line.classList.contains("folio-line-final-compressed")) {\n          previousCorrectedScale = null;\n          continue;\n        }\n        const content = line.querySelector<HTMLElement>(":scope > .folio-line-content");\n        if (!content) {\n          previousCorrectedScale = null;\n          continue;\n        }\n        let rendered = content.getBoundingClientRect().width;\n        const measure = line.getBoundingClientRect().width;\n        const protrusion = Number(line.dataset.folioRightProtrusion ?? 0);\n        const opticalMeasure = measure + protrusion;\n        let correctedScale = Number(line.dataset.folioGlyphScale ?? 1);\n        if (rendered <= 0 || opticalMeasure <= 0 || !Number.isFinite(correctedScale)) {\n          previousCorrectedScale = null;\n          continue;\n        }\n\n        const lineFontSize = px(getComputedStyle(line).fontSize) || fontSize;\n        const releaseGapFloor = Math.max(1.5, lineFontSize * 0.12);\n        const semanticGapMinimum = () => {\n          const lineWords = [...line.querySelectorAll<HTMLElement>(".folio-word")];\n          let minimum = Number.POSITIVE_INFINITY;\n          for (let index = 1; index < lineWords.length; index++) {\n            if (lineWords[index].dataset.folioSpaceBefore !== "true") continue;\n            minimum = Math.min(\n              minimum,\n              lineWords[index].getBoundingClientRect().left - lineWords[index - 1].getBoundingClientRect().right,\n            );\n          }\n          return minimum;\n        };\n\n        const minimumGap = semanticGapMinimum();\n        if (Number.isFinite(minimumGap) && minimumGap < releaseGapFloor - 0.005) {\n          // This should be sub-pixel only because fitLine already enforced the\n          // same floor. Do not widen a line by several pixels after breaking.\n          const deficit = releaseGapFloor - minimumGap;\n          if (deficit > 0.20) {\n            line.dataset.folioGapViolation = "true";\n          } else {\n            const currentWordSpacing = Number(line.dataset.folioWordSpacing ?? 0);\n            line.style.wordSpacing = `${baseWordSpacing + currentWordSpacing + deficit / Math.max(0.98, correctedScale)}px`;\n            line.dataset.folioWordSpacing = String(currentWordSpacing + deficit / Math.max(0.98, correctedScale));\n          }\n        }\n\n        rendered = content.getBoundingClientRect().width;\n        if (rendered > 0) {\n          correctedScale = Math.max(0.98, Math.min(1.01, correctedScale * opticalMeasure / rendered));\n          if (previousCorrectedScale !== null) {\n            correctedScale = Math.max(\n              previousCorrectedScale - maxAdjacentScaleDelta,\n              Math.min(previousCorrectedScale + maxAdjacentScaleDelta, correctedScale),\n            );\n            correctedScale = Math.max(0.98, Math.min(1.01, correctedScale));\n          }\n          content.style.transform = Math.abs(correctedScale - 1) > 0.00001\n            ? "scaleX(" + correctedScale + ")"\n            : "";\n          line.dataset.folioGlyphScale = String(correctedScale);\n        }\n\n        const finalMinimumGap = semanticGapMinimum();\n        if (Number.isFinite(finalMinimumGap)) {\n          line.dataset.folioMinSemanticGap = String(finalMinimumGap);\n          if (finalMinimumGap < releaseGapFloor - 0.005) line.dataset.folioGapViolation = "true";\n        }\n        previousCorrectedScale = correctedScale;\n      }\n'''
if text.count(cal_old) != 1:
    raise SystemExit(f"server compositor calibration anchor: expected 1, found {text.count(cal_old)}")
compositor.write_text(text.replace(cal_old, cal_new), encoding="utf-8")

# The last print gate validates both the physical page boundary and physical word
# gaps *after* Paged.js and any final page-fit scale correction.
render_print = root / "server/pipeline/render-print.ts"
text = render_print.read_text(encoding="utf-8")
old = '''      let checked = 0;\n      let violations = 0;\n      let worstPx = 0;\n      let sample = "";\n      let minimumScale = 1;\n      for (const line of lines) {\n        const pageNode = line.closest<HTMLElement>(".pagedjs_page");\n        const area = pageNode?.querySelector<HTMLElement>(".pagedjs_area")\n          ?? pageNode?.querySelector<HTMLElement>(".pagedjs_page_content");\n        const content = line.querySelector<HTMLElement>(":scope > .folio-line-content");\n        if (!area || !content) continue;\n        checked++;\n        const areaRect = area.getBoundingClientRect();\n        const contentRect = content.getBoundingClientRect();\n        const protrusion = Math.max(0, Number(line.dataset.folioRightProtrusion ?? 0));\n        const scale = Number(line.dataset.folioGlyphScale ?? 1);\n        if (Number.isFinite(scale)) minimumScale = Math.min(minimumScale, scale);\n        const leftOverflow = Math.max(0, areaRect.left - contentRect.left);\n        const rightOverflow = Math.max(0, contentRect.right - areaRect.right - protrusion);\n        const excess = Math.max(leftOverflow, rightOverflow);\n        if (excess > 0.50) {\n          violations++;\n          if (excess > worstPx) {\n            worstPx = excess;\n            sample = (line.textContent ?? "").replace(/\\u00ad/g, "").trim().slice(0, 180);\n          }\n        }\n      }\n      return { checked, violations, worstPx, sample, corrected, largestCorrection, minimumScale };\n    });\n    if (overflow.violations > 0 || overflow.minimumScale < 0.98 - 0.00001) {\n      throw new Error(`Print layout overflow after final page calibration: ${JSON.stringify(overflow)}`);\n    }\n'''
new = '''      let checked = 0;\n      let violations = 0;\n      let worstPx = 0;\n      let sample = "";\n      let minimumScale = 1;\n      let gapViolations = 0;\n      let minimumGapPx = Number.POSITIVE_INFINITY;\n      let gapSample = "";\n      for (const line of lines) {\n        const pageNode = line.closest<HTMLElement>(".pagedjs_page");\n        const area = pageNode?.querySelector<HTMLElement>(".pagedjs_area")\n          ?? pageNode?.querySelector<HTMLElement>(".pagedjs_page_content");\n        const content = line.querySelector<HTMLElement>(":scope > .folio-line-content");\n        if (!area || !content) continue;\n        checked++;\n        const areaRect = area.getBoundingClientRect();\n        const contentRect = content.getBoundingClientRect();\n        const protrusion = Math.max(0, Number(line.dataset.folioRightProtrusion ?? 0));\n        const scale = Number(line.dataset.folioGlyphScale ?? 1);\n        if (Number.isFinite(scale)) minimumScale = Math.min(minimumScale, scale);\n        const leftOverflow = Math.max(0, areaRect.left - contentRect.left);\n        const rightOverflow = Math.max(0, contentRect.right - areaRect.right - protrusion);\n        const excess = Math.max(leftOverflow, rightOverflow);\n        if (excess > 0.50) {\n          violations++;\n          if (excess > worstPx) {\n            worstPx = excess;\n            sample = (line.textContent ?? "").replace(/\\u00ad/g, "").trim().slice(0, 180);\n          }\n        }\n\n        const fontSize = Number.parseFloat(getComputedStyle(line).fontSize) || 16;\n        const gapFloor = Math.max(1.5, fontSize * 0.12);\n        const words = [...line.querySelectorAll<HTMLElement>(".folio-word")];\n        for (let index = 1; index < words.length; index++) {\n          if (words[index].dataset.folioSpaceBefore !== "true") continue;\n          const gap = words[index].getBoundingClientRect().left - words[index - 1].getBoundingClientRect().right;\n          if (gap < minimumGapPx) {\n            minimumGapPx = gap;\n            gapSample = `${words[index - 1].textContent ?? ""} | ${words[index].textContent ?? ""}`;\n          }\n          if (gap + 0.005 < gapFloor) gapViolations++;\n        }\n      }\n      return {\n        checked, violations, worstPx, sample, corrected, largestCorrection, minimumScale,\n        gapViolations, minimumGapPx: Number.isFinite(minimumGapPx) ? minimumGapPx : null, gapSample,\n      };\n    });\n    if (overflow.violations > 0 || overflow.gapViolations > 0 || overflow.minimumScale < 0.98 - 0.00001) {\n      throw new Error(`Print layout quality failure after final page calibration: ${JSON.stringify(overflow)}`);\n    }\n'''
if text.count(old) != 1:
    raise SystemExit(f"final print quality gate anchor: expected 1, found {text.count(old)}")
render_print.write_text(text.replace(old, new), encoding="utf-8")

print("Applied physical gap-aware line breaking and final print gap gate.")
